/**
 * LPC sprite catalogue: types, loading and pure helpers.
 *
 * The catalogue (public/assets/lpc/catalog.json) is generated by `npm run assets:lpc`
 * (tools/lpc-import.mjs). Item keys are the upstream LPC sheet-definition names
 * (e.g. `torso_armour_plate`, `weapon_sword_longsword`, `hair_ponytail`, `body`).
 *
 * Nothing in this module touches the DOM, so it also runs in Node (tests, tools, server).
 */
import type { BodyType } from '../../content/schema';

/** Standard LPC animation sheets (64×64 frames). */
export type StandardAnim =
  | 'idle'
  | 'combat_idle'
  | 'walk'
  | 'slash'
  | 'backslash'
  | 'halfslash'
  | 'thrust'
  | 'spellcast'
  | 'shoot'
  | 'hurt'
  | 'jump'
  | 'emote'
  | 'sit';

/** Larger-frame animations used by long weapons; the 64px body is centred in the bigger frame. */
export type CustomAnim =
  | 'slash_oversize'
  | 'slash_reverse_oversize'
  | 'thrust_oversize'
  | 'walk_128'
  | 'slash_128'
  | 'backslash_128'
  | 'halfslash_128'
  | 'thrust_128';

export type SheetAnim = StandardAnim | CustomAnim;

/** Facing. LPC sheet rows are ordered n, w, s, e. */
export type Dir = 'n' | 'e' | 's' | 'w';
export const DIR_ROW: Record<Dir, number> = { n: 0, w: 1, s: 2, e: 3 };

export const STANDARD_ANIMS: readonly StandardAnim[] = [
  'idle', 'combat_idle', 'walk', 'slash', 'backslash', 'halfslash', 'thrust',
  'spellcast', 'shoot', 'hurt', 'jump', 'emote', 'sit',
];
export const CUSTOM_ANIMS: readonly CustomAnim[] = [
  'slash_oversize', 'slash_reverse_oversize', 'thrust_oversize', 'walk_128',
  'slash_128', 'backslash_128', 'halfslash_128', 'thrust_128',
];

export interface AnimGeometry {
  frameSize: number;
  /** Frames (columns) per row. */
  frames: number;
  /** 4 (n, w, s, e) or 1 (hurt — always drawn facing the viewer). */
  rows: number;
  /** Custom anims: the standard animation whose frames regular layers contribute. */
  base?: StandardAnim;
  /** Custom anims: cells[row][col] = "<base>-<dir>,<col>" source frame for regular 64px layers. */
  cells?: string[][];
}

export interface RecolorChannel {
  /** Palette material: body | hair | cloth | metal | eye | wood | all. */
  material: string;
  /** Base palette the source PNG is drawn in, as "version.name" (e.g. "ulpc.light"). */
  base: string;
  /** Hex colours of the base palette (index-mapped to the target palette). */
  source: string[];
  /** Palette sets offered for this channel, as "material.version" (e.g. "body.ulpc", "all.lpcr"). */
  palettes: string[];
  label: string;
  /** Upstream sub-type for secondary channels (e.g. "eyes" on human heads). */
  typeName: string | null;
}

export interface CatalogLayer {
  z: number;
  /** Present when this layer is a whole custom-animation sheet rather than per-anim standard sheets. */
  custom?: CustomAnim;
  /** Directory per body type (relative to the asset base). */
  paths: Partial<Record<BodyType, string>>;
  /** Animations this layer has, for every body in `paths` (array) or per body (record). */
  anims: SheetAnim[] | Partial<Record<BodyType, SheetAnim[]>>;
}

export interface CatalogItem {
  name: string;
  /** Upstream top-level category: body, head, hair, torso, arms, legs, feet, headwear, weapons. */
  category: string;
  /** Curated group in tools/lpc-items.json (heads, hair, helmets, weapons, …). */
  group: string;
  /**
   * Gameplay slot: body, head, ears, eyebrows, hair, beard, torso, cape, waist, hands, arms,
   * shoulders, legs, feet, hat, visor, hat_accessory, neck, weapon, shield, ammo, back, shadow.
   */
  slot: string;
  /** Upstream type_name. */
  type: string;
  tags?: string[];
  /** Upstream required_tags: only meaningful together with an item carrying one of these tags. */
  requires?: string[];
  bodies: BodyType[];
  /** LPC match_body_color: the first recolour channel follows the body's skin colour. */
  matchBodyColor?: boolean;
  /** Palette recolour channels. Index 0 ← LayerRef.color, index 1 ← LayerRef.color2. */
  recolor?: RecolorChannel[];
  /** File variants (separate PNGs per colour). */
  variants?: string[];
  /** When set, palette colours are applied to this file variant (verified exact palette swaps). */
  recolorVariant?: string;
  defaultColor?: string;
  layers: CatalogLayer[];
  /** Weapon family (sword, knife, katana, axe, mace, flail, club, spear, polearm, staff, rod, bow, crossbow, sling, throwing). */
  weapon?: string;
  /** Attack motion family for weapons. */
  attack?: 'slash' | 'thrust' | 'shoot';
  /** Companion items drawn automatically with this one (e.g. arrows with bows). */
  with?: string[];
  licenses: string[];
  /** Upstream sheet-definition path. */
  source: string;
}

export interface PaletteMaterial {
  label: string;
  description: string;
  default: string;
  /** "version.name" of the material's base palette. */
  base: string;
  /** version → colour name → hex colours. */
  versions: Record<string, Record<string, string[]>>;
}

export interface Catalog {
  version: number;
  source: { repo: string; commit: string };
  frameSize: number;
  /** Feet anchor inside a 64px body frame (bottom-centre of the feet). */
  anchor: { x: number; y: number };
  directions: Dir[];
  bodyTypes: BodyType[];
  animations: Record<SheetAnim, AnimGeometry>;
  paletteVersions: Record<string, { label: string; desc: string }>;
  palettes: Record<string, PaletteMaterial>;
  items: Record<string, CatalogItem>;
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

let current: Catalog | null = null;
let pending: Promise<Catalog> | null = null;

/** Base URL of the LPC assets (catalog.json and PNGs). */
export function defaultAssetBase(): string {
  let base = '/';
  try {
    base = (import.meta as unknown as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? '/';
  } catch {
    /* not running under Vite */
  }
  return `${base.replace(/\/?$/, '/')}assets/lpc/`;
}

/** Fetch and memoise the catalogue. */
export function loadCatalog(url: string = defaultAssetBase() + 'catalog.json'): Promise<Catalog> {
  if (current) return Promise.resolve(current);
  if (!pending) {
    pending = fetch(url)
      .then((r) => {
        if (!r.ok) throw new Error(`Failed to load sprite catalogue ${url}: ${r.status}`);
        return r.json() as Promise<Catalog>;
      })
      .then((c) => setCatalog(c))
      .catch((e) => {
        pending = null;
        throw e;
      });
  }
  return pending;
}

/** Install a catalogue directly (tests, Node tools, preloaded bundles). */
export function setCatalog(c: Catalog): Catalog {
  validateCatalogShape(c);
  current = c;
  pending = Promise.resolve(c);
  itemAnimCache.clear();
  return c;
}

/** The loaded catalogue, or throws if `loadCatalog()` has not resolved yet. */
export function getCatalog(): Catalog {
  if (!current) throw new Error('Sprite catalogue not loaded: await loadCatalog() first');
  return current;
}

export function getCatalogIfLoaded(): Catalog | null {
  return current;
}

function validateCatalogShape(c: Catalog): void {
  if (!c || typeof c !== 'object' || c.version !== 1 || !c.items || !c.animations) {
    throw new Error('Invalid sprite catalogue');
  }
}

// ---------------------------------------------------------------------------
// Pure helpers
// ---------------------------------------------------------------------------

export function isCustomAnim(anim: SheetAnim): anim is CustomAnim {
  return (CUSTOM_ANIMS as readonly string[]).includes(anim);
}

/** Animations a layer has for a body (empty when the layer does not exist for that body). */
export function layerAnims(layer: CatalogLayer, body: BodyType): readonly SheetAnim[] {
  if (!layer.paths[body]) return [];
  return Array.isArray(layer.anims) ? layer.anims : layer.anims[body] ?? [];
}

/** File path (relative to the asset base) of a layer sheet. `variant` only for file-variant items. */
export function layerFile(
  layer: CatalogLayer,
  body: BodyType,
  anim: SheetAnim,
  variant?: string | null,
): string | null {
  const dir = layer.paths[body];
  if (!dir || !layerAnims(layer, body).includes(anim)) return null;
  const v = variant ? variant.replaceAll(' ', '_') : '';
  if (layer.custom) return `${dir}${v}.png`;
  return v ? `${dir}${anim}/${v}.png` : `${dir}${anim}.png`;
}

const itemAnimCache = new Map<string, ReadonlySet<SheetAnim>>();

/**
 * Animations an item contributes to for a body, including custom anims reached through
 * their base animation (an item with a "slash" sheet also appears in "slash_oversize").
 */
export function itemAnims(catalog: Catalog, key: string, body: BodyType): ReadonlySet<SheetAnim> {
  const cacheKey = `${key}|${body}`;
  const hit = catalog === current ? itemAnimCache.get(cacheKey) : undefined;
  if (hit) return hit;
  const item = catalog.items[key];
  const set = new Set<SheetAnim>();
  if (item && item.bodies.includes(body)) {
    for (const layer of item.layers) for (const a of layerAnims(layer, body)) set.add(a);
    for (const c of CUSTOM_ANIMS) {
      const base = catalog.animations[c]?.base;
      if (base && set.has(base)) set.add(c);
    }
  }
  if (catalog === current) itemAnimCache.set(cacheKey, set);
  return set;
}

/** Animations whose sheets the item itself provides (no base-anim inheritance). */
export function itemOwnAnims(catalog: Catalog, key: string, body: BodyType): ReadonlySet<SheetAnim> {
  const item = catalog.items[key];
  const set = new Set<SheetAnim>();
  if (item && item.bodies.includes(body)) for (const layer of item.layers) for (const a of layerAnims(layer, body)) set.add(a);
  return set;
}

/** Keys of all items in a slot, optionally filtered by body type. */
export function itemsInSlot(catalog: Catalog, slot: string, body?: BodyType): string[] {
  return Object.entries(catalog.items)
    .filter(([, it]) => it.slot === slot && (!body || it.bodies.includes(body)))
    .map(([k]) => k);
}

/**
 * Every colour name a channel accepts, as keys usable in LayerRef.color.
 * Default-version colours are bare names ("navy"); others are qualified ("lpcr.navy",
 * "all.lpcr.aegean"), matching the upstream generator's recolour keys.
 */
export function channelColors(catalog: Catalog, channel: RecolorChannel): string[] {
  const out: string[] = [];
  const mat = catalog.palettes[channel.material];
  for (const token of channel.palettes) {
    const [m, v] = token.split('.');
    const pal = catalog.palettes[m]?.versions[v];
    if (!pal) continue;
    const prefix = (m !== channel.material ? `${m}.` : '') + (v !== mat?.default || m !== channel.material ? `${v}.` : '');
    for (const name of Object.keys(pal)) out.push(prefix + name);
  }
  return [...new Set(out)];
}

/** Colour choices for an item's channel (file variants first for channel 0). */
export function itemColorChoices(catalog: Catalog, key: string, channel = 0): string[] {
  const item = catalog.items[key];
  if (!item) return [];
  const out: string[] = [];
  if (channel === 0 && item.variants) out.push(...item.variants.filter((v) => v !== item.recolorVariant));
  const ch = item.recolor?.[channel];
  if (ch && (channel > 0 || !item.variants || item.recolorVariant)) out.push(...channelColors(catalog, ch));
  return [...new Set(out)];
}
